def t(en, zh, ja, es):
    translations[en] = {'zh':zh, 'ja':ja, 'es':es}
    return ''.join(f'<span class="{lang}">{text}</span>' for lang,text in zip(('en','zh','ja','es'),(en,zh,ja,es)))

def feature(n, field):
    return t(*(data[n-1][lang][field] if field != 'title' else ' '.join(data[n-1][lang][field]) for lang in ('en-US','zh-Hans','ja','es')))

def img(n, eager=False, sizes='(max-width: 700px) 90vw, 85vw'):
    m = media[str(n)]['en']
    width,height = m['width'],m['height']
    src = f'assets/product/v173/{n}-en-1280.webp'
    srcset = ', '.join(f'assets/product/v173/{n}-en-{w}.webp {w}w' for w in (640,1280,1920))
    return f'<img data-image="{n}" src="{src}" srcset="{srcset}" sizes="{sizes}" width="{width}" height="{height}" alt="{escape(data[n-1]["en-US"]["screenLabel"])}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""} style="aspect-ratio:{width}/{height}">'

def cards(numbers, category):
    result = '<div class="feature-grid">'
    for n in numbers:
        result += f'<article class="feature-card" data-reveal><a href="#detail-{n}" class="feature-open" data-detail="{n}"><div class="card-copy"><p class="eyebrow">{category}</p><h3>{feature(n,"title")}</h3><p class="card-description">{feature(n,"description")}</p></div><div class="card-image">{img(n, sizes="(max-width: 600px) 90vw, (max-width: 900px) 44vw, 360px")}</div><span class="plus" aria-hidden="true">+</span><span class="sr-only">{t("Explore feature","查看功能详情","機能を見る","Explorar función")}</span></a></article>'
    return result+'</div>'

