html.append(f'''<section class="hdr" id="hdr"><div class="wrap"><div class="hdr-heading" data-reveal><p class="eyebrow">{t('A BRIGHTER PERSPECTIVE','高光之上，还有细节。','ハイライトの、その先へ。','OTRA DIMENSIÓN DE LUZ')}</p><h2>{t('The real workspace.<br><em>The real highlights.</em>','真实工作台。<br><em>真实 HDR 高光。</em>','実際の画面で。<br><em>本来のハイライトを。</em>','El espacio real.<br><em>La luz real.</em>')}</h2><p>{t('SDR on the left. The original HDR image on the right. See both, inside the app interface.','左侧 SDR，右侧原始 HDR。保留真实应用界面，直接观察图像的高光层次。','左に SDR、右にオリジナルの HDR。アプリ画面の中で、両方を確認できます。','SDR a la izquierda, HDR original a la derecha. Observa ambos dentro de la interfaz.')}</p></div><div class="hdr-app-composite" aria-label="HDR and SDR in the actual app interface">{img(3,sizes='(max-width: 700px) 94vw, 1180px')}<div class="native-photo sdr-native"><img src="assets/product/v173/_DSC0828-1-sdr.avif" width="1000" height="667" alt="Original SDR AVIF photograph" loading="lazy" decoding="async"></div><div class="native-photo hdr-native"><img src="assets/product/v173/_DSC0828-1.avif" width="1000" height="667" alt="Original HDR AVIF photograph" loading="lazy" decoding="async"></div></div><div class="hdr-bottom"><span>SDR <span class="muted">/</span> HDR</span><p>{t('To see the full HDR highlight range, use a compatible HDR display and browser. On SDR displays, differences may be limited.','完整 HDR 高光表现需要支持 HDR 的屏幕与浏览器；在 SDR 屏幕上，显示差异可能有限。','HDR の明るさをすべて見るには、対応画面とブラウザが必要です。SDR 画面では違いが小さい場合があります。','Para ver todo el rango HDR, usa una pantalla y navegador compatibles. En pantallas SDR, la diferencia puede ser limitada.')}</p></div></div></section>''')
html.append(f'<section class="toolbox wrap" id="highlights"><div class="section-head" data-reveal><p class="eyebrow">{t("THE REST OF YOUR WORKFLOW","一站式，不止于调色。","ワークフローの、続きを。","EL RESTO DE TU FLUJO")}</p><h2>{t("From selection.<br>To something worth sharing.","从挑选。<br>到值得分享的作品。","選ぶところから。<br>共有できる作品まで。","De seleccionar.<br>A crear algo que compartir.")}</h2><p>{t("Review, rank, compress, stitch and animate. Keep the next step within reach.","评审、Rank、压缩、拼图与 GIF。让图像工作流的下一步，始终触手可及。","レビュー、順位付け、圧縮、結合、GIF。次の操作も、すぐ手元に。","Evalúa, ordena, comprime, une y anima. El siguiente paso, siempre a mano.")}</p></div>{cards([4,10,7,21,6,11,5,12,8,3,22,23], t("IMAGE WORKSPACE","图像工作空间","画像ワークスペース","ESPACIO DE IMAGEN"))}<p class="more-tools">{t("Also at hand: crop, resize, rotate, batch rename and star ratings.","还有：裁剪、缩放、旋转、批量重命名与星级评级。","さらに、切り抜き、サイズ変更、回転、一括名前変更、星評価も。","También: recortar, redimensionar, girar, renombrar por lotes y puntuar.")}</p></section>')
